from pathlib import Path
import base64,gzip
root=Path(__file__).resolve().parents[1]
payloads={'data/capacity/normalized/1401/capacities-microbiology.csv': '', 'data/capacity/normalized/1401/capacities-cell-molecular-biology.csv': '',
'data/capacity/normalized/1402/capacities-microbiology.csv': '',
'data/capacity/normalized/1402/capacities-cell-molecular-biology.csv': '[... ELLIPSIZATION ...]',
'data/capacity/MICROBIOLOGY_REPORT.md': '',
'data/capacity/MICROBIOLOGY_SUMMARY.json': '',
'data/capacity/CELL_MOLECULAR_BIOLOGY_REPORT.md': '',
'data/capacity/CELL_MOLECULAR_BIOLOGY_SUMMARY.json': ''}
for rel,data in payloads.items():
    out=root/rel
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_bytes(gzip.decompress(base64.b64decode(data)))
    print("wrote",rel)
